import json

async def execute(self, inputs):
    from src.runtime.assets.assembly import get_asset_placement_engine, EnvironmentPlan

    env_plan_json = str(inputs.get('environment_plan_json') or '')
    if not env_plan_json.strip():
        self.log_error('[AssetPlacement] environment_plan_json is required.')
        return {'placement_plan_json': '{}', 'plan_id': '', 'total_placed': 0, 'zone_counts_json': '{}', 'ok': False, 'exec_out': True}

    try:
        env_dict = json.loads(env_plan_json)
        env_plan = EnvironmentPlan.from_dict(env_dict)

        engine = get_asset_placement_engine()
        plan   = engine.generate_placement_plan(env_plan)

        self.log_info(
            f'[AssetPlacement] {env_plan.environment!r}: '
            f'{plan.total_placed} asset(s) placed, ok={plan.ok}'
        )
        if plan.warnings:
            for w in plan.warnings:
                self.log_warning(f'[AssetPlacement] {w}')

        return {
            'placement_plan_json': json.dumps(plan.to_dict()),
            'plan_id':        plan.plan_id,
            'total_placed':   plan.total_placed,
            'zone_counts_json': json.dumps(plan.zone_counts),
            'ok':             plan.ok,
            'exec_out':       True,
        }
    except Exception as e:
        self.log_error(f'[AssetPlacement] {e}')
        return {'placement_plan_json': '{}', 'plan_id': '', 'total_placed': 0, 'zone_counts_json': '{}', 'ok': False, 'exec_out': True}

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Asset_Placement(BaseNode):
        name = 'hou_mcp_asset_placement'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Asset_Placement
